package dev.theredstonee.trsclient.ornithe;
import com.google.gson.*;
import java.nio.file.*;
import java.util.*;
/** Explicit local export of measured frame timings and bindings, without player/server/config text. */
public final class OrnitheDiagnostics {
 private OrnitheDiagnostics(){}
 public static void export(OrnitheClient c){var report=new JsonObject();report.addProperty("farTerrainShader",c.farTerrain.shaderDiagnostic());report.addProperty("schema",1);report.addProperty("version",c.version());report.addProperty("java",System.getProperty("java.version"));report.addProperty("os",System.getProperty("os.name"));report.addProperty("width",c.mc.width);report.addProperty("height",c.mc.height);report.addProperty("renderer",org.lwjgl.opengl.GL11.glGetString(org.lwjgl.opengl.GL11.GL_RENDERER));report.addProperty("glVersion",org.lwjgl.opengl.GL11.glGetString(org.lwjgl.opengl.GL11.GL_VERSION));report.addProperty("argentum",net.fabricmc.loader.api.FabricLoader.getInstance().isModLoaded("argentum"));report.addProperty("lwjgl3",net.fabricmc.loader.api.FabricLoader.getInstance().isModLoaded("legacy-lwjgl3"));
  int count=Math.min(c.frameCount,c.frameNanos.length);long[] frames=Arrays.copyOf(c.frameNanos,count);Arrays.sort(frames);report.addProperty("frames",count);if(count>0){report.addProperty("frameTimeP50Ms",frames[(count-1)/2]/1e6);report.addProperty("frameTimeP95Ms",frames[(int)((count-1)*.95)]/1e6);report.addProperty("frameTimeP99Ms",frames[(int)((count-1)*.99)]/1e6);report.addProperty("fpsFromMeanFrameTime",1e9/Arrays.stream(frames).average().orElseThrow());}report.addProperty("heapUsedBytes",Runtime.getRuntime().totalMemory()-Runtime.getRuntime().freeMemory());report.addProperty("ownedDynamicTextures",c.canvas.ownedDynamicTextures());report.addProperty("ownedDynamicTextureBytes",c.canvas.ownedDynamicTextureBytes());report.addProperty("fontBatchesSinceReady",c.canvas.glyphBatches);report.addProperty("mapSampledColumns",c.map.sampledTotal());report.addProperty("modInitToReadyMs",c.readyNanos==0?0:(c.readyNanos-c.initNanos)/1e6);report.addProperty("lastWorldLoadMs",c.lastWorldLoadMs);
  JsonObject modules=new JsonObject();for(var m:c.modules.registry.all()){var cap=c.capabilities.get(m.id());var value=new JsonObject();value.addProperty("enabled",m.isEnabled());value.addProperty("runnable",c.capabilities.runnable(m));value.addProperty("state",cap.state().name());modules.add(m.id(),value);}report.add("modules",modules);String json=new GsonBuilder().setPrettyPrinting().create().toJson(report);Path file=c.mc.gameDir.toPath().resolve("tflcore-diagnostics").resolve("frames-"+System.currentTimeMillis()+".json");c.mapPlatform.message("Saving local diagnostics: "+file.getFileName());Thread worker=new Thread(()->{try{Files.createDirectories(file.getParent());Files.writeString(file,json);OrnitheClient.LOG.info("Diagnostics written to {}",file);}catch(java.io.IOException error){OrnitheClient.LOG.error("Diagnostic export failed",error);}},"TFL-Diagnostics");worker.setDaemon(true);worker.start();}
}
